WITH valid_web_events AS (SELECT *, CASE WHEN duration_sec >= 426 THEN 'High' WHEN duration_sec >= 74 THEN 'Medium' ELSE 'Low' END AS duration_sec_band FROM web_events WHERE HOUR(event_time) BETWEEN 11 AND 18 OR duration_sec BETWEEN 160 AND 214), agg AS (SELECT event_type, COUNT(*) AS row_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values FROM valid_web_events GROUP BY event_type) SELECT event_type, page_values FROM agg WHERE row_count < 5 ORDER BY event_type
